#!/usr/bin/env python3
"""Freeze and reserve the 15m negative-shock rebound sensitivity batch."""
import hashlib,json,subprocess,sys
from pathlib import Path
ROOT=Path(__file__).resolve().parents[3];ROUND=Path(__file__).resolve().parent
sys.path.insert(0,str(ROOT/'research/automation'));import registry

def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
meta=ROOT/'research/experiments/20261012T035429Z/report.json';source=json.loads(meta.read_text());filters=source['plan']['execution']['filters']
prior_path=ROOT/'research/experiments/20261012T035429Z/prior_evidence_audit.json';prior=json.loads(prior_path.read_text());assert len(prior['initial16_actual_results_checked'])==16 and all(x['evidence'] for x in prior['initial16_actual_results_checked'])
files={}
for a in ('BTC','ETH'):
 files[a]=[]
 for suffix in ('20240916T000000Z_20250916T000000Z_transfer_20261001','20250916T000000Z_20260916T000000Z_archive_20260929'):
  p=ROOT/f'data/normalized/binance/{a}/binance_{a}_{suffix}/spot_bars.parquet';files[a].append({'path':str(p.relative_to(ROOT)),'sha256':sha(p),'bytes':p.stat().st_size})
common={'literature':{'citation':'Kitron, N.A. & Wengrowicz, J.M. (2026). Short-horizon mean reversion in cryptocurrency markets: a matched cross-market measurement. arXiv:2608.21888, version accessed 2026-10-12.','url':'https://arxiv.org/abs/2608.21888','accessed_utc':'2026-10-12','use':'The authors report 15-minute directional mean reversion across Binance crypto pairs, but estimate only about 1.3 bp gross edge per trade against a 5 bp benchmark round-trip cost. This fixed one-coin shock/rebound rule is a predeclared implementation test, not a replication; it adds longer rebound targets, own-account execution costs and tail risk.'},
 'data':{'source':'Binance spot closed 1m OHLCV aggregated into UTC 15m bars','files':files,'range_utc':'2024-09-16T00:00:00Z/2026-09-16T00:00:00Z','reuse_disclosure':'The full period is repeatedly used development/validation history; not an untouched final holdout.'},
 'walk_forward':{'window_type':'rolling','train_days':365,'train_15m_bars':35040,'test_days':30,'test_15m_bars':2880,'step_days':30,'embargo_days':3,'embargo_15m_bars':288,'folds':12,'continuous_oos':True,'first_test_index':35328,'end_exclusive_index':69888,'first_oos_execution_utc':'2025-09-19T00:16:00Z','terminal_execution_utc':'2026-09-14T00:16:00Z','parameter_fit':'None; rules and grid frozen before results. Previous closed bars warm only signal/cost inputs; OOS account starts with cash and carries position across contiguous test folds.'},
 'execution':{'filters_source':'research/experiments/20261012T035429Z/report.json','filters_source_sha256':sha(meta),'filters_by_symbol':filters,'reference_price':'On signal close availability at each UTC 15m boundary, execute on the following 15m block first 1m open after one-minute buffer (block_start+60s). Rebound/timeout liquidation follows the same delay. No historical L2 quotes; actual historical 1m OHLCV opens are only reference prices, not exchange fills.'},
 'costs':{'fee_per_side':0.001,'half_spread_estimate_per_side':0.0001,'slippage_per_side':0.0002,'impact_coefficient':0.5,'impact_formula':'0.5 * sample std(previous 20 completed UTC daily log returns) * sqrt(order budget / mean quote turnover(previous 20 complete UTC days)','max_lagged_ADV_participation':0.001,'scenarios':[1,2,3],'spread_counted_once':True,'funding_borrow':'Not applicable; unlevered long-only spot.'},
 'prior_evidence':{'initial16_audit':str(prior_path.relative_to(ROOT)),'initial16_audit_sha256':sha(prior_path),'finding':'All 16 original rows already have actual backtest evidence; this is a new 15m configuration family, not an attempt to relabel old results.'}}
plan={'round':ROUND.name,'frozen_at_utc':'2026-10-12T19:24:14Z','direction':'15m long-only spot mean-reversion after large negative candle, with full rebound target and maximum holding timeout','economic_falsification':'Recent primary-source evidence estimates roughly 1.3bp gross reversal edge versus 5bp benchmark round-trip costs. The repository cost model is materially higher (10bp fee per side before spread/slippage/impact); keep the actual costly simulation to measure the specific full-rebound rule and turnover, with no expectation of profitability.', 'hypothesis':'Some large short-horizon selloffs may mean-revert before a fixed short holding cap. Longer holding caps can capture rebounds but increase exposure to continuing declines; larger entry shocks reduce frequency. Costs are likely to dominate at the repository fee assumption, making this a falsification-oriented historical test.', 'grid':{'assets':['BTC','ETH'],'entry_15m_drop_fraction':[0.005,0.01,0.02],'max_holding_15m_bars':[1,4,12],'initial_capital_usdt_per_config':2000,'exit_rebound_fraction':0.0},'sensitivity_axes':['entry_15m_drop_fraction','max_holding_15m_bars'],'rule':'At completed UTC 15m signal bar j, compute r=C[j]/C[j-1]-1. If flat and r<=-entry_drop_fraction, buy long on the next 15m block at block_start+60s; record C[j] as the recovery reference and the 15m bar index of execution. While long, use only completed 15m closes: exit when C[j]>=recovery_reference, or when j-entry_execution_bar_index>=max_holding_15m_bars, whichever occurs first. Exit at next block_start+60s. After any exit, no same-bar re-entry; later completed bars may generate new entries. Signals use closes only, do not peek into the following bar, and the exit cap is a hard time stop rather than a price stop. Cash/units persist; no leverage, short, scale-in, interest, or OOS warm-up trades.', 'allocation':'Each asset/parameter definition is a separate 2,000 USDT long-only spot account with at most one position; no transfer or simultaneous cross-asset position.', 'failure_gates':{'all_1x_2x_3x_returns_positive':True,'minimum_positive_1x_folds':7,'maximum_3x_minute_close_sample_drawdown_pct':25,'minimum_3x_neighborhood_positive_fraction':0.60,'minimum_1x_round_trips':2,'minimum_1x_gross_reference_pnl_to_cost':2.5,'no_cash_or_units_violations':True,'terminal_flat':True,'interpretation':'A pass would be only a repeated-history screen; it is not independent OOS or live-profit evidence.'},**common}
(ROUND/'spec.json').write_text(json.dumps(plan,indent=2,ensure_ascii=False)+'\n')
rows=[]
for a in ('BTC','ETH'):
 for threshold in (0.005,0.01,0.02):
  for hold in (1,4,12):
   name=f'reversal_drop{int(threshold*10000):03d}_hold{hold}_{a}'
   spec={'kind':'strategy','family':'spot-intraday-shock-rebound','market':'spot','timeframe':'15m','universe':[a+'/USDT'],'name':name,
    'logic':{'entry':'At a newly closed UTC 15m bar j, compute simple return close[j]/close[j-1]-1. If flat and return <= -entry_15m_drop_fraction (equality qualifies), enter long at next 15m block first one-minute open after one-minute availability buffer.', 'rebound_exit':'Store signal close[j] as recovery_reference. On later completed 15m closes, exit if close[j] >= recovery_reference (equality qualifies).', 'time_exit':'Also exit once j-entry_execution_bar_index >= max_holding_15m_bars. If both rebound and timeout conditions occur together, process one full exit. Exit executes at next block first minute open after a one-minute buffer.', 'state':'After exit, do not re-enter on the same decision bar. Retry no rejected historical fill retroactively; this is a bar-close backtest with the next-block minute-open reference. Start OOS flat.', 'sizing':'Independent $2,000 maximum-affordable unlevered spot; preserve USDT residue; no shorting, leverage, add-on, cross-asset exposure, cash yield, or pre-OOS fills.'},
    'parameters':{'entry_15m_drop_fraction':threshold,'max_holding_15m_bars':hold,'exit_rebound_fraction':0.0,'initial_capital_usdt':2000,'train_15m_bars':35040,'test_15m_bars':2880,'step_15m_bars':2880,'embargo_15m_bars':288,'folds':12,'oos_start_15m_index':35328,'oos_end_exclusive_15m_index':69888,'cost_multipliers':[1,2,3]}}
   p=ROUND/'specs'/f'{name}.json';p.write_text(json.dumps(spec,indent=2)+'\n');rows.append({'name':name,'asset':a,'spec':str(p.relative_to(ROOT)),'fingerprint':registry.fingerprint(spec),'is_comparator':False})
for a in ('BTC','ETH'):
 name=f'hold_360d_{a}';spec={'kind':'strategy','family':'spot-intraday-hold-reference','market':'spot','timeframe':'15m','universe':[a+'/USDT'],'name':name,'logic':{'entry':'Buy at first OOS next-block minute-open reference, irrespective of signal.','exit':'Hold to shared terminal execution and liquidate at cost.','sizing':'Independent $2,000 unlevered long-only spot benchmark; no cash yield.'},'parameters':{'initial_capital_usdt':2000,'oos_start_15m_index':35328,'oos_end_exclusive_15m_index':69888,'cost_multipliers':[1,2,3]}}
 p=ROUND/'specs'/f'{name}.json';p.write_text(json.dumps(spec,indent=2)+'\n');rows.append({'name':name,'asset':a,'spec':str(p.relative_to(ROOT)),'fingerprint':registry.fingerprint(spec),'is_comparator':True})
(ROUND/'batch.json').write_text(json.dumps(rows,indent=2)+'\n')
with (ROUND/'reserve.log').open('w') as f:
 for row in rows:
  cp=subprocess.run([sys.executable,str(ROOT/'research/automation/registry.py'),'reserve',str(ROOT/row['spec'])],cwd=ROOT,text=True,capture_output=True)
  f.write(json.dumps({'name':row['name'],'returncode':cp.returncode,'stdout':cp.stdout.strip(),'stderr':cp.stderr.strip()},ensure_ascii=False)+'\n');f.flush()
  if cp.returncode:raise SystemExit(f"reserve failed {row['name']}: {cp.returncode} {cp.stderr}")
print('reserved',len(rows),'unique definitions before evaluation')
